  put('s_h2', 8, 'fig', '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="押す力と摩擦力のグラフ(質量2.0kg、μ=0.50、μ′=0.30)。止まっている間は静止摩擦力が押す力と等しく、最大摩擦力9.8Nをこえるとすべり出し、動摩擦力は約5.9Nで一定"><line x1="30" y1="130" x2="212" y2="130" class="ax"/><line x1="30" y1="130" x2="30" y2="16" class="ax"/><path d="M30 130 L140.7 48.7" class="cv"/><line x1="140.7" y1="48.7" x2="140.7" y2="81.2" class="dash"/><path d="M140.7 81.2 L205.2 81.2" class="cv2"/><circle cx="140.7" cy="48.7" r="3" class="pt"/><line x1="30" y1="48.7" x2="140.7" y2="48.7" class="dash"/><text x="27" y="52.7" text-anchor="end">9.8</text><text x="27" y="85.2" text-anchor="end">5.9</text><text x="34" y="14">摩擦力[N]</text><text x="212" y="144" text-anchor="end">押す力[N]</text><text x="140.7" y="144" text-anchor="middle">9.8</text><text x="134.7" y="44.7" text-anchor="end">最大摩擦力 μN</text><text x="146.7" y="75.2">動摩擦力 μ′N</text><text x="70" y="112">静止摩擦力</text><text x="70" y="124">= 押す力</text><text x="80" y="32" text-anchor="middle">止まっている</text><text x="186" y="32" text-anchor="middle">すべる</text></svg>');
  put('s_energy', 4, 'fig', '<svg viewBox="0 0 220 160" class="lz-fig" role="img" aria-label="重力による位置エネルギーU=mghは基準の高さから測る。2kgの物体が5mの高さなら98J、基準より下では負になる。ばねの弾性エネルギーはU=½kx²で、100N/mのばねを0.2m縮めると2J"><text x="6" y="14">重力:U = mgh</text><line x1="10" y1="110" x2="100" y2="110" class="cv"/><text x="12" y="124">基準 h=0</text><circle cx="55" cy="36" r="7" class="tr"/><text x="66" y="32">2kg</text><line x1="30" y1="108" x2="30" y2="40" class="ax"/><path d="M31.9 43.5 L30 40 L28.1 43.5" class="ax"/><line x1="30" y1="40" x2="30" y2="108" class="ax"/><path d="M28.1 104.5 L30 108 L31.9 104.5" class="ax"/><text x="4" y="76">5m</text><text x="40" y="64">U=2×9.8×5</text><text x="56" y="78">=98J</text><circle cx="55" cy="138" r="7" class="tr"/><text x="66" y="142">下は負</text><line x1="112" y1="10" x2="112" y2="150" class="dash"/><text x="120" y="14">ばね:U = ½kx²</text><line x1="122" y1="30" x2="122" y2="70" class="ax"/><path d="M122 50 L128 50 L132 42 L138 58 L144 42 L150 58 L156 42 L160 50 L166 50" class="cv"/><rect x="166" y="38" width="26" height="24" class="bx"/><line x1="166" y1="66" x2="166" y2="80" class="ax"/><line x1="192" y1="66" x2="192" y2="80" class="dash"/><line x1="190" y1="74" x2="168" y2="74" class="cv2"/><path d="M171.5 72.1 L168 74 L171.5 75.9" class="cv2"/><text x="146" y="92">x 縮める</text><text x="120" y="110">k=100N/m</text><text x="120" y="124">x=0.2m</text><text x="120" y="140">U=½×100×0.2²</text><text x="120" y="154"> =2J</text></svg>');
